import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const l="/img/Speech.png",m=JSON.parse('{"title":"语音","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/Speech.md","filePath":"ai-dive/Speech.md","lastUpdated":null}'),h={name:"ai-dive/Speech.md"};function o(n,a,s,p,c,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="语音" tabindex="-1">语音 <a class="header-anchor" href="#语音" aria-label="Permalink to &quot;语音&quot;">​</a></h1><p>技能(skill)，类似于APP，是指可以通过语音交互为用户提供一个或多个特定的功能和服务。</p><h2 id="语音交互" tabindex="-1">语音交互 <a class="header-anchor" href="#语音交互" aria-label="Permalink to &quot;语音交互&quot;">​</a></h2><p>语音交互也是非常热门的方向之一，其实语音交互整个流程里包含语音识别、自然语言处理和语音合成。自然语言处理很多时候是作为单独的一个领域来研究的，自然语言处理见其他章节，所以此处只介绍语音识别和语音合成。[^8]</p><h2 id="为什么开发语音对话技能" tabindex="-1">为什么开发语音对话技能？ <a class="header-anchor" href="#为什么开发语音对话技能" aria-label="Permalink to &quot;为什么开发语音对话技能？&quot;">​</a></h2><ol><li>语音对话技能可以解放双手，在一些眼睛、双手被占用的场合，也能便捷获取服务。比如，在汽车驾驶、厨房等场景下，可以对着一台智能设备说“放首好听的歌”、“提醒我5分钟后把火调小点”，不干扰双手正在做的动作。</li><li>服务体验更直接、更高效。比如，在一个有屏设备上想听蔡健雅的歌曲，通过触屏交互方式需要打开音乐软件、打字输入歌手名、搜索、返回结果后选择播放等几个步骤，但在对话交互方式下，只需对着有屏设备说“我想听首蔡健雅的歌”即可，一步直达。</li><li>通过语音对话让视觉障碍者方便获取到更多的互联网服务。</li><li>语音对话交互新形式，作为一种行业热门和趋势，值得很多创新企业进行一定的投入和探索，避免未来在市场中的被动。 [^2]</li></ol><p><img src="'+l+'" alt="设计语音对话系统的5个要点[3]"></p><h2 id="asr" tabindex="-1">ASR <a class="header-anchor" href="#asr" aria-label="Permalink to &quot;ASR&quot;">​</a></h2><h3 id="研究内容" tabindex="-1">研究内容 <a class="header-anchor" href="#研究内容" aria-label="Permalink to &quot;研究内容&quot;">​</a></h3><p>语音识别的输入是声音，属于计算机无法直接处理的模拟信号，所以需要将声音转化成计算机能处理的文字信息。传统的识别方式需要通过编码将其转变为数字信号，并提取其中的特征进行处理。</p><p>传统方式的声学模型一般采用隐马尔可夫模型（HMM），处理流程是语音输入——编码（特征提取）——解码——输出。</p><p>还有一种“端到端”的识别方式，一般采用深度神经网络（DNN），这种方式的声学模型的输入通常可以使用更原始的信号特征（减少了编码阶段的工作），输出也不再必须经过音素等底层元素，可以直接是字母或者汉字。</p><p>在计算资源与模型的训练数据充足的情况下，“端到端”方式往往能达到更好的效果。目前的语音识别技术主要是通过DNN实现的。语音识别的效果一般用“识别率”，即识别文字与标准文字相匹配的字数与标准文字总字数的比例来衡量。目前中文通用语音连续识别的识别率最高可以达到97%。</p><h3 id="衍生研究内容" tabindex="-1">衍生研究内容 <a class="header-anchor" href="#衍生研究内容" aria-label="Permalink to &quot;衍生研究内容&quot;">​</a></h3><ul><li>麦克风阵列：在家庭、会议室、户外、商场等各种环境下，语音识别会有噪音、混响、人声干扰、回声等各种问题。在这种需求背景下可以采用麦克风阵列来解决。麦克风阵列由一定数目的声学传感器（一般是麦克风）组成，用来对声场的空间特性进行采样并处理的系统，可以实现语音增强、声源定位、去混响、声源信号提取/分离。麦克风阵列又分为：2麦克风阵列、4麦克风阵列、6麦克风阵列、6+1麦克风阵列。随着麦克风数量的增多，拾音的距离，噪声抑制，声源定位的角度，以及价格都会不同，所以要贴合实际应用场景来找到最佳方案。</li><li>远场语音识别：解决远场语音识别需要结合前后端共同完成。前端使用麦克风阵列硬件，解决噪声、混响、回声等带来的问题，后端则利用近场远场的声学规律不同构建适合远场环境的声学模型，前后端共同解决远场识别的问题。</li><li>语音唤醒：通过关键词唤醒语音设备，通常都是3个音节以上的关键词。例如：嘿Siri、和亚马逊echo的Alexa。语音唤醒基本是在本地进行的，必须在设备终端运行，不能切入云平台。因为一个7×24小时监听的设备要保护用户隐私，只能做本地处理，而不能将音频流联网进行云端处理。 语音唤醒对唤醒响应时间、功耗、唤醒效果都有要求。 语音激活检测：判断外界是否有有效语音，在低信噪比的远场尤为重要。</li></ul><p>资料合集｜语音识别该如何学习呢？ - 深蓝学院的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/396583057" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/396583057</a></p><p><a href="https://github.com/flashlight/flashlight/tree/master/flashlight/app/asr" target="_blank" rel="noreferrer">https://github.com/flashlight/flashlight/tree/master/flashlight/app/asr</a></p><h2 id="语音合成-tts" tabindex="-1">语音合成（TTS） <a class="header-anchor" href="#语音合成-tts" aria-label="Permalink to &quot;语音合成（TTS）&quot;">​</a></h2><h3 id="研究内容-1" tabindex="-1">研究内容 <a class="header-anchor" href="#研究内容-1" aria-label="Permalink to &quot;研究内容&quot;">​</a></h3><p>是将文字转化为语音（朗读出来）的过程，目前有两种实现方法，分别是：拼接法和参数法。</p><p>拼接法是把事先录制的大量语音切碎成基本单元存储起来，再根据需要选取拼接而成。这种方法输出语音质量较高，但是数据库要求过大。 参数法是通过语音提取参数再转化为波形，从而输出语音。这种方法的数据库要求小，但是声音不可避免会有机械感。 DeepMind早前发布了一个机器学习语音生成模型WaveNet，直接生成原始音频波形，可以对任意声音建模，不依赖任何发音理论模型，能够在文本转语音和常规的音频生成上得到出色的结果。</p><h3 id="瓶颈" tabindex="-1">瓶颈 <a class="header-anchor" href="#瓶颈" aria-label="Permalink to &quot;瓶颈&quot;">​</a></h3><p>个性化TTS数据需求量大，在用户预期比较高的时候难满足。需要AI产品经理选择用户预期不苛刻的场景，或者在设计时管理好用户预期。[^8]</p><h2 id="提供相关方案的企业" tabindex="-1">提供相关方案的企业 <a class="header-anchor" href="#提供相关方案的企业" aria-label="Permalink to &quot;提供相关方案的企业&quot;">​</a></h2><ul><li>讯飞开放平台（提供语音识别、语音合成、语音扩展等技术方案及智能硬件以及多种行业解决方案）：<a href="https://www.xfyun.cn/" target="_blank" rel="noreferrer">https://www.xfyun.cn/</a></li><li>图灵机器人（提供多场景的聊天机器人解决方案）：<a href="http://www.tuling123.com/" target="_blank" rel="noreferrer">http://www.tuling123.com/</a></li><li>腾讯AI开放平台（提供语音识别、语音合成等技术）：<a href="https://ai.qq.com/" target="_blank" rel="noreferrer">https://ai.qq.com/</a></li><li>百度AI开放平台（提供语音识别、语音合成等技术）：<a href="http://ai.baidu.com/tech/speech" target="_blank" rel="noreferrer">http://ai.baidu.com/tech/speech</a></li><li>阿里云（提供语音识别、语音合成、录音文件识别等）：<a href="https://ai.aliyun.com/?spm=a2c4g.11174283.1146454.294.167d1039G3kvVD" target="_blank" rel="noreferrer">https://ai.aliyun.com/?spm=a2c4g.11174283.1146454.294.167d1039G3kvVD</a></li><li>追一科技（提供智能外呼、及智能机器人在多行业的解决方案）：<a href="https://zhuiyi.ai/" target="_blank" rel="noreferrer">https://zhuiyi.ai/</a></li></ul><h2 id="相关产业" tabindex="-1">相关产业 <a class="header-anchor" href="#相关产业" aria-label="Permalink to &quot;相关产业&quot;">​</a></h2><ol><li>虚拟个人助理产业：Siri、微软小娜、百度度秘、谷歌Assistant、助理来也等等；</li><li>智能音箱产业：Amazon Echo、Google Home、叮咚、小爱、小雅、天猫精灵等等；[^4]</li><li>声音克隆产业：LOVO Studio“克隆”出的声音带有情感特征，真实感更强[^10]</li></ol><h2 id="一个好的语音产品需要" tabindex="-1">一个好的语音产品需要： <a class="header-anchor" href="#一个好的语音产品需要" aria-label="Permalink to &quot;一个好的语音产品需要：&quot;">​</a></h2><ol><li>准确率高的nlu，asr</li><li>意图匹配规则用 模糊匹配和完全匹配相结合</li><li>支持多语言、多口音</li><li>词典要完整、更新及时、标准化处理（同义词都指向词典里的一个词，也就是同义词合并）</li><li>声纹识别，可以精准定位正在使用的用户</li><li>多模态，就是视觉触觉语音等全部结合。简单一点来说，如果产品界面和语音打通的话，当用户说查一下哪吒。根据最上层的应用是音乐、视频、阅读来判定用户是想听歌还是想看电影还是想搜小说 ，因为一个用户指令是可以匹配到多个意图的，要动态的根据具体情况对意图进行排序选择</li><li>泛化能力，就是模糊匹配准确度高，可以标准化词典或者词槽，设置覆盖面广的语气词表等 [^5]</li></ol><h2 id="通用智能语音助手产品设计难点" tabindex="-1">通用智能语音助手产品设计难点？ <a class="header-anchor" href="#通用智能语音助手产品设计难点" aria-label="Permalink to &quot;通用智能语音助手产品设计难点？&quot;">​</a></h2><ol><li>海量的数据：搜索、闲聊、其他应用</li><li>CPS（ Conversations Per Session）：CPS描述了人类与人工智能在一次对话中持续的平均轮数，从而反映了人工智能在这些对话中所体现的沟通能力。 从传统Q&amp;A问答到多轮对话，从被动回答到主动对话。</li><li>人性化：形象设定（语料运营）、NLG（自然语言生成）、TTS（语音合成） <blockquote><p>⚠️ 【图片缺失：通用智能语音助手产品】（原引用文件不存在，待补）</p></blockquote></li><li>投入产出比低：依赖技术突破（NLU）、用户习惯培养、持续优化（保持数据的时效性）[^7]</li></ol><p>语音识别[^6]</p><h2 id="动态交互" tabindex="-1">动态交互 <a class="header-anchor" href="#动态交互" aria-label="Permalink to &quot;动态交互&quot;">​</a></h2><p>在语音对话等场景下，产品的功能是需要在和用户的动态交互中被唤起的。</p><p>当然这里主要谈到的是语音对话等场景下，大部分用在搜索、推荐等传统界面内的AI交互还是和互联网界面一样。</p><p>而语音场景下和用户不断对话的情况，涉及到了场景剧本编写、多轮对话设计、词槽设计等方面，还有语音交互的规则以及经验。</p><p>比如地图应用的小助手使用场景多在开车用户开车时，用户会问些什么，怎样编写剧本，怎样进行词槽填充？[^9]</p><h2 id="music" tabindex="-1">Music <a class="header-anchor" href="#music" aria-label="Permalink to &quot;Music&quot;">​</a></h2><p>听歌识曲是怎么实现的? - QQ音乐的回答 - 知乎 <a href="https://www.zhihu.com/question/22050701/answer/763616763" target="_blank" rel="noreferrer">https://www.zhihu.com/question/22050701/answer/763616763</a> [^1]: <a href="https://www.msra.cn/zh-cn/news/features/book-recommendation-speech" target="_blank" rel="noreferrer">https://www.msra.cn/zh-cn/news/features/book-recommendation-speech</a> [^2]: <a href="https://dingdang.qq.com/doc/page/32" target="_blank" rel="noreferrer">https://dingdang.qq.com/doc/page/32</a> [^3]: <a href="http://www.woshipm.com/ai/1695480.html" target="_blank" rel="noreferrer">http://www.woshipm.com/ai/1695480.html</a> [^4]: <a href="https://mp.weixin.qq.com/s?__biz=MjM5NzA5OTAwMA==&amp;mid=2650005836&amp;idx=1&amp;sn=832b8ed27a68753ee48536d9bf4abb79&amp;chksm=bed865db89afeccd75b81debbc8a05031b708b645a44d44fba65fa4c9ea2b27474ea9bbab520&amp;scene=21#wechat_redirect" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s?__biz=MjM5NzA5OTAwMA==&amp;mid=2650005836&amp;idx=1&amp;sn=832b8ed27a68753ee48536d9bf4abb79&amp;chksm=bed865db89afeccd75b81debbc8a05031b708b645a44d44fba65fa4c9ea2b27474ea9bbab520&amp;scene=21#wechat_redirect</a> [^5]: <a href="https://zhuanlan.zhihu.com/p/80824253" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/80824253</a> [^6]: <a href="https://www.bilibili.com/video/BV1q5411V7tT?from=search&amp;seid=781442368629495599" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1q5411V7tT?from=search&amp;seid=781442368629495599</a> [^7]: <a href="https://blog.csdn.net/acelit/article/details/77902490" target="_blank" rel="noreferrer">https://blog.csdn.net/acelit/article/details/77902490</a> [^8]: <a href="https://zhuanlan.zhihu.com/p/384020411" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/384020411</a> [^9]: <a href="https://zhuanlan.zhihu.com/p/34557616" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/34557616</a> [^10]: <a href="https://www.zhihu.com/question/303541452/answer/1278981481" target="_blank" rel="noreferrer">https://www.zhihu.com/question/303541452/answer/1278981481</a></p>',39)])])}const u=e(h,[["render",o]]);export{m as __pageData,u as default};
